<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/auth.php';admin_requerido();$error='';$editar=null;
if($_SERVER['REQUEST_METHOD']==='POST'){validar_csrf();try{$accion=$_POST['accion']??'';if($accion==='guardar'){$id=(int)($_POST['id']??0);$local=(int)($_POST['equipo_local_id']??0);$visitante=(int)($_POST['equipo_visitante_id']??0);$fecha=str_replace('T',' ',$_POST['fecha_hora']??'');$estado=$_POST['estado']??'programado';$pl=($_POST['puntos_local']??'')!==''?(int)$_POST['puntos_local']:null;$pv=($_POST['puntos_visitante']??'')!==''?(int)$_POST['puntos_visitante']:null;if(!$local||!$visitante||$local===$visitante)throw new RuntimeException('Selecciona dos equipos diferentes.');if(!$fecha)throw new RuntimeException('Indica fecha y hora.');if(!in_array($estado,['programado','finalizado','suspendido'],true))throw new RuntimeException('Estado no válido.');if($estado==='finalizado'&&($pl===null||$pv===null||$pl<0||$pv<0))throw new RuntimeException('Un partido finalizado necesita ambos marcadores, mayores o iguales a cero.');if($estado!=='finalizado'){$pl=null;$pv=null;}if($id){$s=$pdo->prepare('UPDATE partidos SET equipo_local_id=?,equipo_visitante_id=?,fecha_hora=?,puntos_local=?,puntos_visitante=?,estado=? WHERE id=?');$s->execute([$local,$visitante,$fecha,$pl,$pv,$estado,$id]);}else{$s=$pdo->prepare('INSERT INTO partidos(equipo_local_id,equipo_visitante_id,fecha_hora,puntos_local,puntos_visitante,estado) VALUES(?,?,?,?,?,?)');$s->execute([$local,$visitante,$fecha,$pl,$pv,$estado]);}header('Location: partidos.php?ok=1');exit;}elseif($accion==='eliminar'){$s=$pdo->prepare('DELETE FROM partidos WHERE id=?');$s->execute([(int)$_POST['id']]);header('Location: partidos.php?eliminado=1');exit;}}catch(Throwable $ex){$error=$ex instanceof PDOException?'No se pudo guardar el partido. Revisa los datos ingresados.':$ex->getMessage();}}
if(isset($_GET['editar'])){$s=$pdo->prepare('SELECT * FROM partidos WHERE id=?');$s->execute([(int)$_GET['editar']]);$editar=$s->fetch();}$equipos=$pdo->query('SELECT id,nombre FROM equipos ORDER BY nombre')->fetchAll();$partidos=$pdo->query('SELECT p.*,el.nombre AS local_nombre,ev.nombre AS visitante_nombre FROM partidos p JOIN equipos el ON el.id=p.equipo_local_id JOIN equipos ev ON ev.id=p.equipo_visitante_id ORDER BY p.fecha_hora DESC')->fetchAll();$fechaValue=$editar?date('Y-m-d\TH:i',strtotime($editar['fecha_hora'])):'';$pageTitle='Gestionar partidos';require __DIR__.'/../src/header.php';?>
<section class="page-intro"><span class="eyebrow">ADMINISTRACIÓN</span><h1>Partidos y resultados</h1><p>Programa encuentros y registra los marcadores al finalizar.</p></section><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['ok'])):?><div class="alert alert-success">Partido guardado correctamente.</div><?php endif;?><?php if(isset($_GET['eliminado'])):?><div class="alert alert-success">Partido eliminado.</div><?php endif;?><?php if(count($equipos)<2):?><div class="alert alert-error">Necesitas al menos dos equipos para programar un partido.</div><?php endif;?>
<div class="admin-two-col"><form class="form-card" method="post"><h2><?=$editar?'Editar partido':'Programar partido'?></h2><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="guardar"><input type="hidden" name="id" value="<?=(int)($editar['id']??0)?>"><label>Equipo local<select name="equipo_local_id" required><?php foreach($equipos as $eq):?><option value="<?=(int)$eq['id']?>" <?=((int)($editar['equipo_local_id']??0)===(int)$eq['id'])?'selected':''?>><?=e($eq['nombre'])?></option><?php endforeach;?></select></label><label>Equipo visitante<select name="equipo_visitante_id" required><?php foreach($equipos as $eq):?><option value="<?=(int)$eq['id']?>" <?=((int)($editar['equipo_visitante_id']??0)===(int)$eq['id'])?'selected':''?>><?=e($eq['nombre'])?></option><?php endforeach;?></select></label><label>Fecha y hora<input type="datetime-local" name="fecha_hora" required value="<?=e($fechaValue)?>"></label><label>Estado<select name="estado"><option value="programado" <?=($editar['estado']??'programado')==='programado'?'selected':''?>>Programado</option><option value="finalizado" <?=($editar['estado']??'')==='finalizado'?'selected':''?>>Finalizado</option><option value="suspendido" <?=($editar['estado']??'')==='suspendido'?'selected':''?>>Suspendido</option></select></label><div class="form-row"><label>Puntos local<input type="number" min="0" name="puntos_local" value="<?=e($editar['puntos_local']??'')?>"></label><label>Puntos visitante<input type="number" min="0" name="puntos_visitante" value="<?=e($editar['puntos_visitante']??'')?>"></label></div><p class="field-hint">Para registrar un marcador, cambia el estado a “Finalizado” e ingresa ambos puntajes.</p><button class="btn" type="submit" <?=count($equipos)<2?'disabled':''?>>Guardar partido</button><?php if($editar):?><a class="back-link" href="partidos.php">Cancelar edición</a><?php endif;?></form><section><h2 class="list-title">Encuentros (<?=count($partidos)?>)</h2><?php if(!$partidos):?><div class="empty-state">No hay partidos registrados.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Encuentro</th><th>Fecha</th><th>Marcador</th><th>Acciones</th></tr></thead><tbody><?php foreach($partidos as $p):?><tr><td><strong><?=e($p['local_nombre'])?></strong><small class="table-sub">vs. <?=e($p['visitante_nombre'])?></small><small class="table-sub"><?=e(ucfirst($p['estado']))?></small></td><td><?=e(date('d/m/Y H:i',strtotime($p['fecha_hora'])))?></td><td><?= $p['estado']==='finalizado'?(int)$p['puntos_local'].' – '.(int)$p['puntos_visitante']:'—' ?></td><td class="actions-cell"><a href="?editar=<?=(int)$p['id']?>">Editar</a><form method="post" onsubmit="return confirm('¿Eliminar este partido?');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="link-danger" type="submit">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div><?php require __DIR__.'/../src/footer.php';?>